import json

with open("mcp-agent-ml-research-read_registry-1778768209331.txt", "r") as f:
    raw = json.load(f)

result = json.loads(raw["result"])
experiments = result["data"]["experiments"]

# Target experiment groups
target_prefixes = [
    "plan001", "plan002", "plan003",
    "plan005", "plan006",
    "plan009",
    "plan012", "plan013", "plan014",
    "plan016", "plan017", "plan018",
    "sta-"
]

def extract_numeric(obj, prefix=""):
    """Recursively extract all numeric values from a dict."""
    nums = {}
    if isinstance(obj, dict):
        for k, v in obj.items():
            full_key = f"{prefix}.{k}" if prefix else k
            if isinstance(v, (int, float)) and not isinstance(v, bool):
                nums[full_key] = v
            elif isinstance(v, str):
                # Try parsing numeric strings
                try:
                    fv = float(v)
                    nums[full_key] = fv
                except (ValueError, TypeError):
                    pass
            elif isinstance(v, dict):
                nums.update(extract_numeric(v, full_key))
            elif isinstance(v, list):
                for i, item in enumerate(v):
                    nums.update(extract_numeric(item, f"{full_key}[{i}]"))
    return nums

for exp_id in sorted(experiments.keys()):
    exp = experiments[exp_id]

    # Print all experiments, not just targeted ones
    print(f"\n{'='*80}")
    print(f"EXP: {exp_id}")
